export type ImportanceFamily = "exceptional" | "currency" | "unique" | "waystone" | "jewel" | "flask" | "charm" | "misc";

export type ImportanceOption = {
  value: string;
  label: string;
  note: string;
};

export type FilterItem = {
  id: string;
  label: string;
  labelKo?: string;
  note?: string;
  family?: ImportanceFamily;
  baseType?: string;
  defaultImportance?: string;
  levelingImportance?: string;
  sourceSection?: string;
  levelingException?: boolean;
  defaultNote?: string;
  gemLevel?: number;
  waystoneTier?: number;
  classNames?: string[];
  rarity?: "Normal" | "Magic" | "Rare" | "Unique";
  uniqueNamesKo?: string[];
  originalNeverSinkTier?: "T1" | "T2" | "MULTI-HIGH" | "MULTI" | "T3-BOSS" | "T3" | "T4" | "REST";
  exceptionalRule?: "overquality" | "oversocket";
  filterConditions?: string[];
};

export type ItemGroup = {
  id: string;
  title: string;
  subtitle?: string;
  items: FilterItem[];
};

export type GearCategory = {
  id: string;
  label: string;
  labelKo: string;
  classes: string[];
};

export type NormalGearBase = {
  id: string;
  baseType: string;
  labelKo: string;
};

export type NormalGearGroup = GearCategory & {
  items: NormalGearBase[];
};

export type GearTier = {
  id: string;
  tier: number;
  label: string;
  note: string;
  defaultImportance: string;
};

export type NeverSinkStrictnessId =
  | "0-SOFT"
  | "1-REGULAR"
  | "2-SEMI-STRICT"
  | "3-STRICT"
  | "4-VERY-STRICT"
  | "5-UBER-STRICT"
  | "6-UBER-PLUS-STRICT";

export type NeverSinkStrictnessOption = {
  id: NeverSinkStrictnessId;
  ko: string;
  note: string;
  localPath: string;
  source: string;
};

