function uniqueWeaponItem(
  id: string,
  baseType: string,
  labelKo: string,
  uniqueNamesKo: string[],
  originalNeverSinkTier: FilterItem["originalNeverSinkTier"],
): FilterItem {
  const defaultImportance = (() => {
    switch (originalNeverSinkTier) {
      case "T1":
        return "t1";
      case "T2":
        return "t2";
      case "MULTI-HIGH":
      case "MULTI":
        return "x";
      case "T3-BOSS":
      case "T3":
        return "t3";
      case "T4":
        return "t4";
      default:
        return "default";
    }
  })();

  return {
    id,
    label: baseType,
    labelKo,
    note: `관련 고유: ${uniqueNamesKo.join(" / ")}`,
    family: "unique",
    baseType,
    rarity: "Unique",
    defaultImportance,
    sourceSection: "Weapon Unique / BaseType",
    defaultNote: "드롭 시 필터가 구분하는 BaseType 기준. 초기 중요도는 NeverSink 0-SOFT 원본 Tier를 그대로 표시합니다.",
    uniqueNamesKo,
    originalNeverSinkTier,
  };
}


