function uniqueArmourItem(
  id: string,
  baseType: string,
  labelKo: string,
  originalNeverSinkTier: FilterItem["originalNeverSinkTier"],
): FilterItem {
  const uniqueNamesKo = UNIQUE_ARMOUR_NAMES_KO[baseType] ?? [];
  const defaultImportance = (() => {
    switch (originalNeverSinkTier) {
      case "T1":
        return "t1";
      case "T2":
        return "t2";
      case "MULTI-HIGH":
      case "MULTI":
        return "x";
      case "T3-BOSS":
      case "T3":
        return "t3";
      case "T4":
        return "t4";
      default:
        return "default";
    }
  })();

  return {
    id,
    label: baseType,
    labelKo,
    note: uniqueNamesKo.length ? `관련 고유: ${uniqueNamesKo.join(" / ")}` : "현재 DB에서 관련 고유명을 확인하지 못했습니다.",
    family: "unique",
    baseType,
    rarity: "Unique",
    defaultImportance,
    sourceSection: "Armour Unique / BaseType",
    defaultNote: "드롭 시 필터가 구분하는 BaseType 기준. 초기 중요도는 NeverSink 0-SOFT 원본 Tier를 그대로 표시합니다.",
    uniqueNamesKo,
    originalNeverSinkTier,
  };
}

