function otherUniqueItem(
  id: string,
  baseType: string,
  labelKo: string,
  uniqueNamesKo: string[],
  originalNeverSinkTier: FilterItem["originalNeverSinkTier"],
): FilterItem {
  return {
    ...uniqueWeaponItem(id, baseType, labelKo, uniqueNamesKo, originalNeverSinkTier),
    sourceSection: "Other Unique / BaseType",
    defaultNote: "PoE2DB Other 고유 중 기존 전용 카테고리(주얼·플라스크·호신부·서판)를 제외한 항목입니다. 드롭 BaseType 기준으로 통합하며 초기 중요도는 NeverSink 0-SOFT 원본 Tier를 그대로 표시합니다.",
  };
}

