function normalBaseId(categoryId: string, baseType: string) {
  return `normal-${categoryId}-${baseType.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")}`;
}

export const NORMAL_GEAR_GROUPS: NormalGearGroup[] = GEAR_CATEGORIES.map((category) => ({
  ...category,
  items: (NORMAL_GEAR_BASES_BY_CATEGORY[category.id] ?? []).map((item) => ({
    id: normalBaseId(category.id, item.baseType),
    baseType: item.baseType,
    labelKo: item.labelKo,
  })),
}));

